/**
 * Task-driven admission: two physical GPU owners and one latest dirty state.
 * Presentation eligibility belongs to the transaction coordinator, not this
 * credit counter. There is no elapsed-frame floor or completion publication gate.
 * Every action is interned; steady-state scheduling allocates nothing.
 */
export type MailboxAction =
  | { readonly kind: 'render-now' }
  | { readonly kind: 'wait-fence' }
  | { readonly kind: 'none' };

const ACTION_NONE: MailboxAction = { kind: 'none' };
const ACTION_RENDER_NOW: MailboxAction = { kind: 'render-now' };
const ACTION_WAIT_FENCE: MailboxAction = { kind: 'wait-fence' };
export const MAX_IN_FLIGHT_RENDER_FRAMES = 2;

export interface RenderMailbox {
  noteDirty(): MailboxAction;
  noteSubmitted(): MailboxAction;
  noteRenderAborted(): MailboxAction;
  noteFrameComplete(): MailboxAction;
  reset(): void;
}

export function createRenderMailbox(): RenderMailbox {
  let dirty = false;
  let inFlight = 0;
  let awaitingSubmit = false;

  function advance(): MailboxAction {
    if (awaitingSubmit || !dirty) return ACTION_NONE;
    if (inFlight >= MAX_IN_FLIGHT_RENDER_FRAMES) return ACTION_WAIT_FENCE;
    awaitingSubmit = true;
    dirty = false;
    return ACTION_RENDER_NOW;
  }

  return {
    noteDirty(): MailboxAction {
      dirty = true;
      return advance();
    },
    noteSubmitted(): MailboxAction {
      if (!awaitingSubmit) throw new Error('render submission without a mailbox claim');
      if (inFlight >= MAX_IN_FLIGHT_RENDER_FRAMES) throw new Error('render credit overflow');
      awaitingSubmit = false;
      inFlight += 1;
      return advance();
    },
    noteRenderAborted(): MailboxAction {
      awaitingSubmit = false;
      dirty = true;
      return ACTION_NONE;
    },
    noteFrameComplete(): MailboxAction {
      if (inFlight === 0) throw new Error('render credit completion without an owner');
      inFlight -= 1;
      return advance();
    },
    reset(): void {
      dirty = false;
      inFlight = 0;
      awaitingSubmit = false;
    },
  };
}

