export type AtlasDirtyRect = readonly [x: number, y: number, width: number, height: number];

/**
 * Upload the current WASM glyph atlas, reallocating the WebGL texture whenever
 * its dimensions change. Returns true when storage was reallocated.
 */
export function uploadAtlasTexture(
  gl: WebGL2RenderingContext,
  texture: WebGLTexture,
  pixels: Uint8Array,
  dirtyRect: AtlasDirtyRect,
  currentWidth: number,
  currentHeight: number,
  nextWidth: number,
  nextHeight: number,
): boolean {
  assertAtlasDimensions(nextWidth, nextHeight, pixels.byteLength);
  const [x, y, width, height] = dirtyRect;
  assertDirtyRect(x, y, width, height, nextWidth, nextHeight);

  const resized = currentWidth !== nextWidth || currentHeight !== nextHeight;
  if (!resized && (width === 0 || height === 0)) return false;

  gl.bindTexture(gl.TEXTURE_2D, texture);
  if (resized) {
    resetUnpackWindow(gl);
    // A dimension change invalidates the old texture storage. Upload the
    // complete atlas in the allocation call so rendering can never observe a
    // resized-but-partially-populated texture.
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.R8,
      nextWidth,
      nextHeight,
      0,
      gl.RED,
      gl.UNSIGNED_BYTE,
      pixels,
    );
    return true;
  }

  gl.pixelStorei(gl.UNPACK_ROW_LENGTH, nextWidth);
  gl.pixelStorei(gl.UNPACK_SKIP_PIXELS, x);
  gl.pixelStorei(gl.UNPACK_SKIP_ROWS, y);
  try {
    gl.texSubImage2D(gl.TEXTURE_2D, 0, x, y, width, height, gl.RED, gl.UNSIGNED_BYTE, pixels);
  } finally {
    resetUnpackWindow(gl);
  }
  return false;
}

function resetUnpackWindow(gl: WebGL2RenderingContext): void {
  gl.pixelStorei(gl.UNPACK_ROW_LENGTH, 0);
  gl.pixelStorei(gl.UNPACK_SKIP_PIXELS, 0);
  gl.pixelStorei(gl.UNPACK_SKIP_ROWS, 0);
}

function assertAtlasDimensions(width: number, height: number, byteLength: number): void {
  if (
    !Number.isSafeInteger(width) ||
    !Number.isSafeInteger(height) ||
    width <= 0 ||
    height <= 0 ||
    width * height !== byteLength
  ) {
    throw new RangeError(`invalid atlas dimensions ${width}x${height} for ${byteLength} bytes`);
  }
}

function assertDirtyRect(
  x: number,
  y: number,
  width: number,
  height: number,
  atlasWidth: number,
  atlasHeight: number,
): void {
  if (
    ![x, y, width, height].every(Number.isSafeInteger) ||
    x < 0 ||
    y < 0 ||
    width < 0 ||
    height < 0 ||
    x + width > atlasWidth ||
    y + height > atlasHeight
  ) {
    throw new RangeError(
      `invalid atlas dirty rect ${x},${y},${width},${height} for ${atlasWidth}x${atlasHeight}`,
    );
  }
}

