import { nextPowerOfTwo } from '@mercury/shared';
import { uploadAtlasTexture } from './atlas-texture-upload';
import { GLYPH_GAMMA_DARK_FOREGROUND, GLYPH_GAMMA_LIGHT_FOREGROUND } from './terminal/glyph-gamma';
import type { TerminalFrameCompletionMode } from './terminal/runtime-policy';
import { DEFAULT_TERMINAL_THEME } from './terminal/themes';
import type { GeometryBufferRange, GeometryVersions, GpuRenderer } from './terminal-renderer';

const INITIAL_INSTANCE_CAPACITY = 220 * 50 * 2;
const INITIAL_CURSOR_INSTANCE_CAPACITY = 1;
const SOLID_VIEWPORT_UNIFORM = 1 << 0;
const GLYPH_VIEWPORT_UNIFORM = 1 << 1;
const CURSOR_VIEWPORT_UNIFORM = 1 << 2;
const ALL_VIEWPORT_UNIFORMS =
  SOLID_VIEWPORT_UNIFORM | GLYPH_VIEWPORT_UNIFORM | CURSOR_VIEWPORT_UNIFORM;

// ── Shader sources ────────────────────────────────────────────────────────────

const SOLID_VERT = `#version 300 es
in vec2 a_corner;
in vec4 a_rect;
in vec3 a_color;
uniform vec2 u_vp;
out vec3 v_color;
void main() {
  vec2 pos = a_rect.xy + a_corner * a_rect.zw;
  gl_Position = vec4((pos / u_vp) * 2.0 - 1.0, 0.0, 1.0);
  gl_Position.y = -gl_Position.y;
  v_color = a_color;
}`;

const SOLID_FRAG = `#version 300 es
precision mediump float;
in vec3 v_color;
out vec4 o;
void main() { o = vec4(v_color, 1.0); }`;

const GLYPH_VERT = `#version 300 es
in vec2 a_corner;
in vec2 a_cell;
in vec2 a_off;
in vec2 a_glyph_size;
in vec4 a_uv;
in vec3 a_fg;
in float a_alpha;
uniform vec2 u_vp;
// highp: the atlas is 2048-4096px square, and a mediump (fp16) UV has ~11 bits
// of mantissa — under one texel of headroom at 4096, which shows up on mobile
// GPUs as glyphs sampling a neighbour's edge.
out highp vec2 v_uv;
out vec3 v_fg;
out float v_alpha;
void main() {
  vec2 pos = a_cell + a_off + a_corner * a_glyph_size;
  gl_Position = vec4((pos / u_vp) * 2.0 - 1.0, 0.0, 1.0);
  gl_Position.y = -gl_Position.y;
  v_uv = a_uv.xy + a_corner * (a_uv.zw - a_uv.xy);
  v_fg = a_fg;
  v_alpha = a_alpha;
}`;

// Coverage gamma. Both constants and the reasoning behind them live in
// `terminal/glyph-gamma.ts`, because the speculative overlay has to apply the
// identical curve through a Canvas 2D lookup — the two drifting apart would
// render a predicted glyph at a different weight from the authoritative glyph
// that replaces it.
const GLYPH_FRAG = `#version 300 es
precision mediump float;
uniform sampler2D u_atlas;
in highp vec2 v_uv;
in vec3 v_fg;
in float v_alpha;
out vec4 o;
void main() {
  float cov = texture(u_atlas, v_uv).r;
  float luma = dot(v_fg, vec3(0.2126, 0.7152, 0.0722));
  cov = pow(cov, mix(${GLYPH_GAMMA_DARK_FOREGROUND.toFixed(2)}, ${GLYPH_GAMMA_LIGHT_FOREGROUND.toFixed(2)}, luma));
  o = vec4(v_fg, cov * v_alpha);
}`;

const CURSOR_VERT = `#version 300 es
in vec2 a_corner;
in vec4 a_rect;
in vec3 a_color;
in float a_shape;
uniform vec2 u_vp;
out vec3 v_color;
out float v_shape;
out vec2 v_local;
void main() {
  vec2 pos = a_rect.xy + a_corner * a_rect.zw;
  gl_Position = vec4((pos / u_vp) * 2.0 - 1.0, 0.0, 1.0);
  gl_Position.y = -gl_Position.y;
  v_color = a_color;
  v_shape = a_shape;
  v_local = a_corner;
}`;

const CURSOR_FRAG = `#version 300 es
precision mediump float;
in vec3 v_color;
in float v_shape;
in vec2 v_local;
out vec4 o;
uniform float u_beam_w;
uniform float u_ul_h;
void main() {
  float inside = 1.0;
  if (v_shape < 0.5) {
    inside = 0.55;
  } else if (v_shape < 1.5) {
    inside = v_local.x <= u_beam_w ? 1.0 : 0.0;
  } else {
    inside = v_local.y >= (1.0 - u_ul_h) ? 1.0 : 0.0;
  }
  vec3 tint = mix(v_color, vec3(1.0), 0.8);
  o = vec4(tint, inside);
}`;

// ── WebGL2Renderer ────────────────────────────────────────────────────────────

export class WebGl2Renderer implements GpuRenderer {
  constructor(
    private readonly contextRestoredCallback?: () => void,
    private readonly completionMode: TerminalFrameCompletionMode = 'gpu-fence',
    private readonly contextLostCallback?: () => void,
  ) {}

  private gl!: WebGL2RenderingContext;
  private atlasW = 0;
  private atlasH = 0;
  private physW = 0;
  private physH = 0;
  private memoryRef: ArrayBuffer | null = null;
  private memoryF32: Float32Array<ArrayBuffer> | null = null;

  // Programs
  private solidProg!: WebGLProgram;
  private glyphProg!: WebGLProgram;
  private cursorProg!: WebGLProgram;

  // Shared unit-quad VBO (6 vertices, 2 components)
  private quadVbo!: WebGLBuffer;

  // Instance VBOs
  private bgVbo!: WebGLBuffer;
  private glyphVbo!: WebGLBuffer;
  private decoVbo!: WebGLBuffer;
  private cursorVbo!: WebGLBuffer;

  // VAOs
  private bgVao!: WebGLVertexArrayObject;
  private glyphVao!: WebGLVertexArrayObject;
  private decoVao!: WebGLVertexArrayObject;
  private cursorVao!: WebGLVertexArrayObject;

  // Atlas texture
  private atlasTex!: WebGLTexture;

  // Uniform locations
  private solidVpLoc!: WebGLUniformLocation;
  private glyphVpLoc!: WebGLUniformLocation;
  private glyphAtlasLoc!: WebGLUniformLocation;
  private cursorVpLoc!: WebGLUniformLocation;
  private cursorBeamWLoc!: WebGLUniformLocation;
  private cursorUlHLoc!: WebGLUniformLocation;
  private bgCapacity = INITIAL_INSTANCE_CAPACITY;
  private glyphCapacity = INITIAL_INSTANCE_CAPACITY;
  private decoCapacity = INITIAL_INSTANCE_CAPACITY;
  private cursorCapacity = INITIAL_CURSOR_INSTANCE_CAPACITY;
  private frameSync: WebGLSync | null = null;
  private syntheticFramePending = false;
  private contextLost = false;
  private canvasRef: OffscreenCanvas | null = null;
  private clearColor: readonly [number, number, number] = DEFAULT_TERMINAL_THEME.background;
  private lastAtlasPixels: Uint8Array | null = null;
  private atlasRestoreSnapshot: Uint8Array | null = null;
  private readonly onContextLost = (event: Event): void => {
    // Declares restore intent. The sync object died with the context;
    // dropping the ref is sufficient (deleteSync on a lost context is a
    // no-op). With contextLost set, GL calls are spec-defined no-ops and
    // no new fences are created, so the scheduler never wedges.
    event.preventDefault();
    this.contextLost = true;
    this.frameSync = null;
    this.clearSyntheticFrameCompletion();
    // WebAssembly memory can grow (detaching the previous view) while the GL
    // context is unavailable. Snapshot the last fully uploaded atlas once on
    // this rare lifecycle path so restore never depends on a stale view.
    this.atlasRestoreSnapshot =
      this.copyAtlasPixelsForRestore(this.lastAtlasPixels) ?? this.atlasRestoreSnapshot;
    this.contextLostCallback?.();
  };
  private readonly onContextRestored = (): void => {
    if (!this.contextLost || this.canvasRef === null) return;
    try {
      // Every object created by the old context is invalid after restoration:
      // rebuild programs, uniforms, buffers, VAOs, and texture storage.
      this.initializeGlResources();
      const atlasPixels =
        this.atlasRestoreSnapshot ?? this.copyAtlasPixelsForRestore(this.lastAtlasPixels);
      if (atlasPixels !== null) {
        uploadAtlasTexture(
          this.gl,
          this.atlasTex,
          atlasPixels,
          [0, 0, this.atlasW, this.atlasH],
          this.atlasW,
          this.atlasH,
          this.atlasW,
          this.atlasH,
        );
      }
      this.atlasRestoreSnapshot = null;
      this.contextLost = false;
      // Recreated buffers are intentionally empty and every geometry version
      // was invalidated. Ask the owner to submit the retained terminal state
      // immediately; otherwise a quiet terminal stays blank until unrelated
      // output happens to schedule another render.
      this.contextRestoredCallback?.();
    } catch (error) {
      // Keep fence polling non-blocking if restore failed. Rethrowing surfaces a
      // worker-health error instead of silently presenting a permanently blank
      // terminal.
      this.contextLost = true;
      throw error;
    }
  };
  private lastBgVersion = -1;
  private lastGlyphVersion = -1;
  private lastDecoVersion = -1;
  private lastCursorVersion = -1;
  private lastViewportWidth = Number.NaN;
  private lastViewportHeight = Number.NaN;
  private viewportUniformsDirty = ALL_VIEWPORT_UNIFORMS;
  private blendEnabled = false;

  async init(
    canvas: OffscreenCanvas,
    atlasW: number,
    atlasH: number,
    clearColor: readonly [number, number, number] = DEFAULT_TERMINAL_THEME.background,
  ): Promise<void> {
    this.atlasW = atlasW;
    this.atlasH = atlasH;
    this.physW = canvas.width;
    this.physH = canvas.height;
    this.clearColor = [clearColor[0], clearColor[1], clearColor[2]];

    const gl = canvas.getContext('webgl2', {
      alpha: false,
      desynchronized: true,
      antialias: false,
    }) as WebGL2RenderingContext | null;
    if (!gl) throw new Error('WebGL2 not available');
    this.gl = gl;
    this.canvasRef = canvas;
    canvas.addEventListener('webglcontextlost', this.onContextLost);
    canvas.addEventListener('webglcontextrestored', this.onContextRestored);
    this.contextLost = false;
    this.initializeGlResources();
  }

  setClearColor(color: readonly [number, number, number]): void {
    this.clearColor = [color[0], color[1], color[2]];
    if (!this.contextLost) {
      this.applyClearColor();
    }
  }

  uploadAtlas(
    pixels: Uint8Array,
    dirtyRect: [number, number, number, number],
    atlasDimensions: readonly [width: number, height: number],
  ): void {
    const [atlasW, atlasH] = atlasDimensions;
    if (this.contextLost) {
      const restoreSnapshot = this.copyAtlasPixelsForRestore(pixels, atlasW, atlasH);
      if (restoreSnapshot === null) {
        throw new RangeError(
          `invalid atlas dimensions ${atlasW}x${atlasH} for ${pixels.byteLength} bytes`,
        );
      }
      this.atlasW = atlasW;
      this.atlasH = atlasH;
      this.lastAtlasPixels = pixels;
      this.atlasRestoreSnapshot = restoreSnapshot;
      return;
    }
    uploadAtlasTexture(
      this.gl,
      this.atlasTex,
      pixels,
      dirtyRect,
      this.atlasW,
      this.atlasH,
      atlasW,
      atlasH,
    );
    this.lastAtlasPixels = pixels;
    this.atlasW = atlasW;
    this.atlasH = atlasH;
  }

  render(
    memory: ArrayBuffer,
    bg: GeometryBufferRange,
    glyph: GeometryBufferRange,
    deco: GeometryBufferRange,
    cursor: GeometryBufferRange,
    viewport: [number, number],
    versions?: GeometryVersions,
  ): void {
    if (this.contextLost) return;
    const gl = this.gl;
    const [vw, vh] = viewport;
    this.ensureInstanceCapacities(bg.count, glyph.count, deco.count, cursor.count);
    if (vw !== this.lastViewportWidth || vh !== this.lastViewportHeight) {
      this.lastViewportWidth = vw;
      this.lastViewportHeight = vh;
      this.viewportUniformsDirty = ALL_VIEWPORT_UNIFORMS;
    }

    gl.clear(gl.COLOR_BUFFER_BIT);

    // bg pass (blend off)
    if (bg.count > 0) {
      this.setBlendEnabled(false);
      if (this.shouldUploadBg(versions)) {
        const bgData = this.viewF32(memory);
        const fullUpload = versions === undefined || this.lastBgVersion < 0;
        this.lastBgVersion = versions?.bg ?? -1;
        this.uploadRange(
          this.bgVbo,
          bgData,
          bg.ptr >>> 2,
          bg.count * 7,
          7,
          fullUpload ? 0 : versions.bgDirtyOffset,
          fullUpload ? bg.count : versions.bgDirtyCount,
        );
      }
      gl.useProgram(this.solidProg);
      this.updateViewportUniform(SOLID_VIEWPORT_UNIFORM, this.solidVpLoc, vw, vh);
      gl.bindVertexArray(this.bgVao);
      gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, bg.count);
    }

    // glyph pass (blend on)
    if (glyph.count > 0) {
      this.setBlendEnabled(true);
      if (this.shouldUploadGlyph(versions)) {
        const glyphData = this.viewF32(memory);
        const fullUpload = versions === undefined || this.lastGlyphVersion < 0;
        this.lastGlyphVersion = versions?.glyph ?? -1;
        this.uploadRange(
          this.glyphVbo,
          glyphData,
          glyph.ptr >>> 2,
          glyph.count * 14,
          14,
          fullUpload ? 0 : versions.glyphDirtyOffset,
          fullUpload ? glyph.count : versions.glyphDirtyCount,
        );
      }
      gl.useProgram(this.glyphProg);
      this.updateViewportUniform(GLYPH_VIEWPORT_UNIFORM, this.glyphVpLoc, vw, vh);
      gl.bindVertexArray(this.glyphVao);
      gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, glyph.count);
    }

    // deco pass (blend off)
    if (deco.count > 0) {
      this.setBlendEnabled(false);
      if (this.shouldUploadDeco(versions)) {
        const decoData = this.viewF32(memory);
        const fullUpload = versions === undefined || this.lastDecoVersion < 0;
        this.lastDecoVersion = versions?.deco ?? -1;
        this.uploadRange(
          this.decoVbo,
          decoData,
          deco.ptr >>> 2,
          deco.count * 7,
          7,
          fullUpload ? 0 : versions.decoDirtyOffset,
          fullUpload ? deco.count : versions.decoDirtyCount,
        );
      }
      gl.useProgram(this.solidProg);
      this.updateViewportUniform(SOLID_VIEWPORT_UNIFORM, this.solidVpLoc, vw, vh);
      gl.bindVertexArray(this.decoVao);
      gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, deco.count);
    }

    // cursor pass (blend on)
    if (cursor.count > 0) {
      this.setBlendEnabled(true);
      if (this.shouldUploadCursor(versions)) {
        const cursorData = this.viewF32(memory);
        const fullUpload = versions === undefined || this.lastCursorVersion < 0;
        this.lastCursorVersion = versions?.cursor ?? -1;
        this.uploadRange(
          this.cursorVbo,
          cursorData,
          cursor.ptr >>> 2,
          cursor.count * 8,
          8,
          fullUpload ? 0 : versions.cursorDirtyOffset,
          fullUpload ? cursor.count : versions.cursorDirtyCount,
        );
      }
      gl.useProgram(this.cursorProg);
      this.updateViewportUniform(CURSOR_VIEWPORT_UNIFORM, this.cursorVpLoc, vw, vh);
      gl.bindVertexArray(this.cursorVao);
      gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, cursor.count);
    }

    // One completion primitive per submitted frame. A prior incomplete frame
    // means an out-of-band resubmit (resize repaint) — replace it; pacing
    // follows only the newest frame.
    if (this.frameSync !== null) gl.deleteSync(this.frameSync);
    this.frameSync = null;
    this.clearSyntheticFrameCompletion();
    if (this.completionMode === 'task-yield') {
      // Mobile WebKit can indefinitely delay fence visibility in this worker
      // path. Flush the submitted commands, then let the owner's fair polling
      // scheduler cross one task boundary before declaring the frame complete.
      // The scheduler supplies actual task-entry evidence; counting polls can
      // release on the same stack or cost a successor an extra task turn.
      gl.flush();
      this.syntheticFramePending = true;
      return;
    }

    this.frameSync = this.contextLost ? null : gl.fenceSync(gl.SYNC_GPU_COMMANDS_COMPLETE, 0);
    // Always submit the draw commands. When fence creation succeeds this also
    // makes the fence observable without waiting for an implicit task commit;
    // when it fails, the frame still reaches the GPU without a completion gate.
    gl.flush();
  }

  frameInFlight(): boolean {
    return this.frameSync !== null || this.syntheticFramePending;
  }

  frameCompletionMode(): TerminalFrameCompletionMode {
    return this.completionMode;
  }

  pollFrameComplete(fromScheduledTask: boolean): boolean {
    if (this.syntheticFramePending) {
      if (this.contextLost) {
        this.clearSyntheticFrameCompletion();
        return true;
      }
      if (!fromScheduledTask) return false;
      this.clearSyntheticFrameCompletion();
      return true;
    }
    const sync = this.frameSync;
    if (sync === null) return true;
    if (this.contextLost) {
      this.frameSync = null;
      return true;
    }
    const gl = this.gl;
    if (gl.getSyncParameter(sync, gl.SYNC_STATUS) !== gl.SIGNALED) return false;
    gl.deleteSync(sync);
    this.frameSync = null;
    return true;
  }

  resize(physW: number, physH: number): void {
    this.physW = physW;
    this.physH = physH;
    if (!this.contextLost) {
      this.gl.viewport(0, 0, physW, physH);
    }
  }

  destroy(): void {
    const gl = this.gl;
    this.clearSyntheticFrameCompletion();
    if (this.frameSync !== null) {
      gl.deleteSync(this.frameSync);
      this.frameSync = null;
    }
    if (this.canvasRef !== null) {
      this.canvasRef.removeEventListener('webglcontextlost', this.onContextLost);
      this.canvasRef.removeEventListener('webglcontextrestored', this.onContextRestored);
      this.canvasRef = null;
    }
    gl.deleteTexture(this.atlasTex);
    for (const vao of [this.bgVao, this.glyphVao, this.decoVao, this.cursorVao]) {
      gl.deleteVertexArray(vao);
    }
    for (const vbo of [this.bgVbo, this.glyphVbo, this.decoVbo, this.cursorVbo, this.quadVbo]) {
      gl.deleteBuffer(vbo);
    }
    for (const prog of [this.solidProg, this.glyphProg, this.cursorProg]) {
      gl.deleteProgram(prog);
    }
    this.contextLost = true;
    this.lastAtlasPixels = null;
    this.atlasRestoreSnapshot = null;
    this.memoryRef = null;
    this.memoryF32 = null;
  }

  private initializeGlResources(): void {
    const gl = this.gl;
    this.frameSync = null;
    this.clearSyntheticFrameCompletion();

    this.solidProg = compileProgram(gl, SOLID_VERT, SOLID_FRAG);
    this.glyphProg = compileProgram(gl, GLYPH_VERT, GLYPH_FRAG);
    this.cursorProg = compileProgram(gl, CURSOR_VERT, CURSOR_FRAG);

    this.solidVpLoc = requireGl(
      gl.getUniformLocation(this.solidProg, 'u_vp'),
      'Missing solid uniform u_vp',
    );
    this.glyphVpLoc = requireGl(
      gl.getUniformLocation(this.glyphProg, 'u_vp'),
      'Missing uniform glyph u_vp',
    );
    this.glyphAtlasLoc = requireGl(
      gl.getUniformLocation(this.glyphProg, 'u_atlas'),
      'Missing uniform u_atlas',
    );
    this.cursorVpLoc = requireGl(
      gl.getUniformLocation(this.cursorProg, 'u_vp'),
      'Missing uniform cursor u_vp',
    );
    this.cursorBeamWLoc = requireGl(
      gl.getUniformLocation(this.cursorProg, 'u_beam_w'),
      'Missing uniform u_beam_w',
    );
    this.cursorUlHLoc = requireGl(
      gl.getUniformLocation(this.cursorProg, 'u_ul_h'),
      'Missing uniform u_ul_h',
    );

    const quadData = new Float32Array([0, 0, 1, 0, 0, 1, 0, 1, 1, 0, 1, 1]);
    this.quadVbo = requireGl(gl.createBuffer(), 'Failed to create quad buffer');
    gl.bindBuffer(gl.ARRAY_BUFFER, this.quadVbo);
    gl.bufferData(gl.ARRAY_BUFFER, quadData, gl.STATIC_DRAW);

    this.bgVbo = createInstanceVbo(gl, this.bgCapacity * 7 * 4);
    this.glyphVbo = createInstanceVbo(gl, this.glyphCapacity * 14 * 4);
    this.decoVbo = createInstanceVbo(gl, this.decoCapacity * 7 * 4);
    this.cursorVbo = createInstanceVbo(gl, this.cursorCapacity * 8 * 4);

    this.bgVao = buildBgVao(gl, this.quadVbo, this.bgVbo, this.solidProg);
    this.glyphVao = buildGlyphVao(gl, this.quadVbo, this.glyphVbo, this.glyphProg);
    this.decoVao = buildBgVao(gl, this.quadVbo, this.decoVbo, this.solidProg);
    this.cursorVao = buildCursorVao(gl, this.quadVbo, this.cursorVbo, this.cursorProg);

    this.atlasTex = requireGl(gl.createTexture(), 'Failed to create atlas texture');
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.atlasTex);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.R8,
      this.atlasW,
      this.atlasH,
      0,
      gl.RED,
      gl.UNSIGNED_BYTE,
      null,
    );
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

    // This renderer owns the context exclusively. Establish invariant state
    // once for the lifetime of these resources instead of rebuilding it for
    // every submitted frame.
    gl.disable(gl.BLEND);
    gl.blendFuncSeparate(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    this.blendEnabled = false;
    gl.useProgram(this.glyphProg);
    gl.uniform1i(this.glyphAtlasLoc, 0);
    gl.useProgram(this.cursorProg);
    gl.uniform1f(this.cursorBeamWLoc, 0.14);
    gl.uniform1f(this.cursorUlHLoc, 0.1);

    gl.viewport(0, 0, this.physW, this.physH);
    this.applyClearColor();
    this.lastBgVersion = -1;
    this.lastGlyphVersion = -1;
    this.lastDecoVersion = -1;
    this.lastCursorVersion = -1;
    this.lastViewportWidth = Number.NaN;
    this.lastViewportHeight = Number.NaN;
    this.viewportUniformsDirty = ALL_VIEWPORT_UNIFORMS;
  }

  private clearSyntheticFrameCompletion(): void {
    this.syntheticFramePending = false;
  }

  private applyClearColor(): void {
    const [red, green, blue] = this.clearColor;
    this.gl.clearColor(red / 255, green / 255, blue / 255, 1);
  }

  private copyAtlasPixelsForRestore(
    pixels: Uint8Array | null,
    width = this.atlasW,
    height = this.atlasH,
  ): Uint8Array | null {
    if (
      pixels === null ||
      !Number.isSafeInteger(width) ||
      !Number.isSafeInteger(height) ||
      width <= 0 ||
      height <= 0 ||
      pixels.byteLength !== width * height
    ) {
      return null;
    }
    try {
      return new Uint8Array(pixels);
    } catch {
      return null;
    }
  }

  private viewF32(memory: ArrayBuffer): Float32Array<ArrayBuffer> {
    if (this.memoryRef !== memory || this.memoryF32 === null) {
      this.memoryRef = memory;
      this.memoryF32 = new Float32Array(memory);
    }
    // WebGL2's source offset/length overload selects the dirty slice directly.
    // Keep this whole-memory view stable instead of allocating one subarray
    // wrapper for every changed geometry pass.
    return this.memoryF32;
  }

  private uploadRange(
    buffer: WebGLBuffer,
    data: Float32Array,
    dataOffset: number,
    dataLength: number,
    stride: number,
    dirtyOffset: number,
    dirtyCount: number,
  ): void {
    if (dirtyCount <= 0) return;
    const start = Math.max(0, dirtyOffset * stride);
    const count = Math.min(
      dataLength - start,
      data.length - dataOffset - start,
      dirtyCount * stride,
    );
    if (count <= 0) return;
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferSubData(gl.ARRAY_BUFFER, start * 4, data, dataOffset + start, count);
  }

  private updateViewportUniform(
    uniform: number,
    location: WebGLUniformLocation,
    width: number,
    height: number,
  ): void {
    if ((this.viewportUniformsDirty & uniform) === 0) return;
    this.gl.uniform2f(location, width, height);
    this.viewportUniformsDirty &= ~uniform;
  }

  private setBlendEnabled(enabled: boolean): void {
    if (this.blendEnabled === enabled) return;
    if (enabled) this.gl.enable(this.gl.BLEND);
    else this.gl.disable(this.gl.BLEND);
    this.blendEnabled = enabled;
  }

  private ensureInstanceCapacities(
    bgCount: number,
    glyphCount: number,
    decoCount: number,
    cursorCount: number,
  ): void {
    const gl = this.gl;
    if (bgCount > this.bgCapacity) {
      this.bgCapacity = nextPowerOfTwo(bgCount);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.bgVbo);
      gl.bufferData(gl.ARRAY_BUFFER, this.bgCapacity * 7 * 4, gl.DYNAMIC_DRAW);
      this.lastBgVersion = -1;
    }

    if (glyphCount > this.glyphCapacity) {
      this.glyphCapacity = nextPowerOfTwo(glyphCount);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.glyphVbo);
      gl.bufferData(gl.ARRAY_BUFFER, this.glyphCapacity * 14 * 4, gl.DYNAMIC_DRAW);
      this.lastGlyphVersion = -1;
    }

    if (decoCount > this.decoCapacity) {
      this.decoCapacity = nextPowerOfTwo(decoCount);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.decoVbo);
      gl.bufferData(gl.ARRAY_BUFFER, this.decoCapacity * 7 * 4, gl.DYNAMIC_DRAW);
      this.lastDecoVersion = -1;
    }

    if (cursorCount > this.cursorCapacity) {
      this.cursorCapacity = nextPowerOfTwo(cursorCount);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.cursorVbo);
      gl.bufferData(gl.ARRAY_BUFFER, this.cursorCapacity * 8 * 4, gl.DYNAMIC_DRAW);
      this.lastCursorVersion = -1;
    }
  }

  private shouldUploadBg(versions: GeometryVersions | undefined): boolean {
    return versions === undefined || versions.bg !== this.lastBgVersion;
  }

  private shouldUploadGlyph(versions: GeometryVersions | undefined): boolean {
    return versions === undefined || versions.glyph !== this.lastGlyphVersion;
  }

  private shouldUploadDeco(versions: GeometryVersions | undefined): boolean {
    return versions === undefined || versions.deco !== this.lastDecoVersion;
  }

  private shouldUploadCursor(versions: GeometryVersions | undefined): boolean {
    return versions === undefined || versions.cursor !== this.lastCursorVersion;
  }
}

// ── GL helpers ────────────────────────────────────────────────────────────────

function compileProgram(gl: WebGL2RenderingContext, vert: string, frag: string): WebGLProgram {
  const vs = requireGl(gl.createShader(gl.VERTEX_SHADER), 'Failed to create vertex shader');
  gl.shaderSource(vs, vert);
  gl.compileShader(vs);
  if (!gl.getShaderParameter(vs, gl.COMPILE_STATUS)) {
    throw new Error(`Vert shader: ${gl.getShaderInfoLog(vs)}`);
  }
  const fs = requireGl(gl.createShader(gl.FRAGMENT_SHADER), 'Failed to create fragment shader');
  gl.shaderSource(fs, frag);
  gl.compileShader(fs);
  if (!gl.getShaderParameter(fs, gl.COMPILE_STATUS)) {
    throw new Error(`Frag shader: ${gl.getShaderInfoLog(fs)}`);
  }
  const prog = requireGl(gl.createProgram(), 'Failed to create shader program');
  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    throw new Error(`Program link: ${gl.getProgramInfoLog(prog)}`);
  }
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  return prog;
}

function createInstanceVbo(gl: WebGL2RenderingContext, byteSize: number): WebGLBuffer {
  const buf = requireGl(gl.createBuffer(), 'Failed to create instance buffer');
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, byteSize, gl.DYNAMIC_DRAW);
  return buf;
}

function attrib(
  gl: WebGL2RenderingContext,
  prog: WebGLProgram,
  name: string,
  size: number,
  stride: number,
  offset: number,
  divisor: number,
): void {
  const loc = gl.getAttribLocation(prog, name);
  if (loc < 0) return;
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, size, gl.FLOAT, false, stride, offset);
  gl.vertexAttribDivisor(loc, divisor);
}

function buildBgVao(
  gl: WebGL2RenderingContext,
  quadVbo: WebGLBuffer,
  instVbo: WebGLBuffer,
  prog: WebGLProgram,
): WebGLVertexArrayObject {
  const vao = createInstancedVao(gl, quadVbo, prog, 'Failed to create background VAO');

  // instance data: rect(4) color(3) = stride 7*4 = 28
  gl.bindBuffer(gl.ARRAY_BUFFER, instVbo);
  const s = 7 * 4;
  attrib(gl, prog, 'a_rect', 4, s, 0, 1);
  attrib(gl, prog, 'a_color', 3, s, 4 * 4, 1);

  gl.bindVertexArray(null);
  return vao;
}

function buildGlyphVao(
  gl: WebGL2RenderingContext,
  quadVbo: WebGLBuffer,
  instVbo: WebGLBuffer,
  prog: WebGLProgram,
): WebGLVertexArrayObject {
  const vao = createInstancedVao(gl, quadVbo, prog, 'Failed to create glyph VAO');

  // instance: cell(2) off(2) glyph_size(2) uv(4) fg(3) alpha(1) = 14 floats, stride 56
  gl.bindBuffer(gl.ARRAY_BUFFER, instVbo);
  const s = 14 * 4;
  attrib(gl, prog, 'a_cell', 2, s, 0, 1);
  attrib(gl, prog, 'a_off', 2, s, 2 * 4, 1);
  attrib(gl, prog, 'a_glyph_size', 2, s, 4 * 4, 1);
  attrib(gl, prog, 'a_uv', 4, s, 6 * 4, 1);
  attrib(gl, prog, 'a_fg', 3, s, 10 * 4, 1);
  attrib(gl, prog, 'a_alpha', 1, s, 13 * 4, 1);

  gl.bindVertexArray(null);
  return vao;
}

function buildCursorVao(
  gl: WebGL2RenderingContext,
  quadVbo: WebGLBuffer,
  instVbo: WebGLBuffer,
  prog: WebGLProgram,
): WebGLVertexArrayObject {
  const vao = createInstancedVao(gl, quadVbo, prog, 'Failed to create cursor VAO');

  // instance: rect(4) color(3) shape(1) = 8 floats, stride 32
  gl.bindBuffer(gl.ARRAY_BUFFER, instVbo);
  const s = 8 * 4;
  attrib(gl, prog, 'a_rect', 4, s, 0, 1);
  attrib(gl, prog, 'a_color', 3, s, 4 * 4, 1);
  attrib(gl, prog, 'a_shape', 1, s, 7 * 4, 1);

  gl.bindVertexArray(null);
  return vao;
}

function createInstancedVao(
  gl: WebGL2RenderingContext,
  quadVbo: WebGLBuffer,
  prog: WebGLProgram,
  errorMessage: string,
): WebGLVertexArrayObject {
  const vao = requireGl(gl.createVertexArray(), errorMessage);
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, quadVbo);
  attrib(gl, prog, 'a_corner', 2, 8, 0, 0);
  return vao;
}

function requireGl<T>(value: T | null, message: string): T {
  if (value === null) {
    throw new Error(message);
  }
  return value;
}

