/**
 * One definition of the glyph coverage gamma curve, shared by the two
 * rasterizers that must agree.
 *
 * `fontdue` produces LINEAR coverage. Both consumers composite it against
 * sRGB-encoded colour — the WebGL2 renderer through
 * `blendFuncSeparate(SRC_ALPHA, ONE_MINUS_SRC_ALPHA, …)` into the default
 * framebuffer, and the speculative overlay by blending the coverage in
 * software over an opaque cell before one `putImageData`. Blending linear
 * coverage in a non-linear space puts 50% coverage of white over black at sRGB
 * 0.500 when `linear_to_srgb(0.5)` = 0.735 is correct. The error is the same
 * size in both contrast directions but reads with the opposite sign:
 * light-on-dark looks thin, dark-on-light looks heavy.
 *
 * Correcting exactly needs the destination pixel, which the shader's blend
 * cannot read; the overlay composes in software and could, but it must draw
 * the same weight the shader will, so it applies the same proxy. That proxy
 * keys the curve off FOREGROUND luminance as a stand-in for which side of the
 * contrast the text sits on. Solving `pow(0.5, g)` against the two extremes
 * gives g = 0.443 for white-on-black and g = 1.918 for black-on-white; one
 * power curve cannot be exact at every coverage, so the shipped pair is pulled
 * toward 1.
 *
 * These live here rather than beside either consumer because the failure mode
 * of them drifting apart is invisible in tests and obvious on screen: with
 * prediction live, a predicted glyph and the authoritative glyph that replaces
 * it would be rendered at different weights.
 *
 * Deliberately absent: a stem-darkening term. It is a taste knob that needs
 * tuning against real text on real hardware, and an untuned magic constant in
 * a per-fragment path is worse than no constant. The curve above is derivable;
 * add stem darkening only with a measured reason.
 */

/** Gamma applied when the foreground is black — dark text on a light ground. */
export const GLYPH_GAMMA_DARK_FOREGROUND = 1.45;

/** Gamma applied when the foreground is white — light text on a dark ground. */
export const GLYPH_GAMMA_LIGHT_FOREGROUND = 0.69;

/** Rec. 709 luma weights, matching the `dot()` in the glyph fragment shader. */
const LUMA_R = 0.2126;
const LUMA_G = 0.7152;
const LUMA_B = 0.0722;

/** Relative luminance of an 8-bit RGB triple, in [0, 1]. */
export function rgbLuma(r: number, g: number, b: number): number {
  return (r * LUMA_R + g * LUMA_G + b * LUMA_B) / 255;
}

/** The exponent to raise coverage to, for a foreground of the given luminance. */
export function glyphCoverageGamma(luma: number): number {
  const clamped = luma < 0 ? 0 : luma > 1 ? 1 : luma;
  return (
    GLYPH_GAMMA_DARK_FOREGROUND +
    (GLYPH_GAMMA_LIGHT_FOREGROUND - GLYPH_GAMMA_DARK_FOREGROUND) * clamped
  );
}

/**
 * Fill a 256-entry coverage lookup for one foreground luminance, in place.
 *
 * The software overlay cannot afford a power per pixel and does not need
 * one: coverage is one byte, so the whole curve is 256 values, rebuilt only
 * when the foreground changes. `scale` folds a constant alpha into the table
 * so the per-pixel blend multiplies by nothing else.
 */
export function fillGlyphCoverageLut(lut: Uint8Array, luma: number, scale: number): void {
  const gamma = glyphCoverageGamma(luma);
  for (let coverage = 0; coverage < 256; coverage += 1) {
    lut[coverage] = Math.round((coverage / 255) ** gamma * 255 * scale);
  }
}

