export interface TaskPollScheduler {
  /** Poll immediately, then enqueue at most one follow-up task while pending. */
  schedule(): void;
  /**
   * Poll right now, even while a follow-up task is already posted.
   *
   * `schedule()` deliberately refuses to poll while a task is in flight, so it
   * cannot answer the question a caller has *at the moment it matters*: the
   * polled operation may well have completed since the last poll, and the
   * pending task is the only thing that would notice — on whatever cadence the
   * task source happens to give.
   */
  pollNow(): void;
  /** Invalidate every already-posted task. */
  cancel(): void;
  /** Dispatch a token received from the injected task queue. */
  handleTask(token: number): void;
}

/**
 * Active-only polling for external state that has no completion callback.
 *
 * The caller supplies an asynchronous task source. Browser callers must use a
 * source that is fair to unrelated task queues. In particular, continuously
 * reposting one MessagePort is not a fairness boundary in Chromium workers and
 * can starve input or display tasks until the polled operation completes.
 */
export function createTaskPollScheduler(
  // True only for an accepted queued task, never immediate/demand polling.
  poll: (fromScheduledTask: boolean) => boolean,
  postTask: (token: number) => void,
): TaskPollScheduler {
  let generation = 1;
  let taskPending = false;
  let active = false;
  let polling = false;
  let rescheduleRequested = false;
  let postingTask = false;
  let inlineTaskToken: number | null = null;
  let inlineTaskChannel: MessageChannel | null = null;

  function closeInlineTaskChannel(): void {
    if (inlineTaskChannel === null) return;
    inlineTaskChannel.port1.close();
    inlineTaskChannel.port2.close();
    inlineTaskChannel = null;
  }

  function deferInlineTask(token: number): void {
    // A real asynchronous task source (the production fair timer) never enters
    // here.
    // Normalize a synchronous injected dispatcher through a task turn so a
    // long-lived fence cannot recurse until the JS stack overflows.
    if (typeof MessageChannel !== 'undefined') {
      if (inlineTaskChannel === null) {
        inlineTaskChannel = new MessageChannel();
        inlineTaskChannel.port1.onmessage = (event: MessageEvent<number>) => {
          scheduler.handleTask(event.data);
        };
      }
      inlineTaskChannel.port2.postMessage(token);
      return;
    }
    setTimeout(() => scheduler.handleTask(token), 0);
  }

  function postNext(): void {
    if (taskPending || !active) return;
    taskPending = true;
    inlineTaskToken = null;
    postingTask = true;
    try {
      postTask(generation);
    } catch (error) {
      inlineTaskToken = null;
      taskPending = false;
      active = false;
      throw error;
    } finally {
      postingTask = false;
    }
    const deliveredInlineToken = inlineTaskToken;
    inlineTaskToken = null;
    if (deliveredInlineToken !== null) {
      try {
        deferInlineTask(deliveredInlineToken);
      } catch (error) {
        taskPending = false;
        active = false;
        throw error;
      }
    }
  }

  function runPoll(fromScheduledTask: boolean): void {
    const runGeneration = generation;
    polling = true;
    rescheduleRequested = false;
    let complete: boolean;
    try {
      complete = poll(fromScheduledTask);
    } finally {
      // A context-loss/driver exception must not leave the scheduler believing
      // it is permanently inside a poll; callers can recover and schedule the
      // replacement renderer's fence on the next turn.
      polling = false;
    }
    if (generation !== runGeneration) return;
    if (!complete) {
      active = true;
      postNext();
      return;
    }
    active = false;
    if (rescheduleRequested) {
      rescheduleRequested = false;
      // The completion callback submitted a new fence. Yield before polling it
      // so an immediately-signaled backlog cannot recurse through the entire
      // render queue on one worker stack.
      active = true;
      postNext();
      return;
    }
    closeInlineTaskChannel();
  }

  const scheduler: TaskPollScheduler = {
    schedule(): void {
      if (polling) {
        // A successful poll may synchronously submit the next GPU frame through
        // its completion callback. Remember that new fence instead of losing it
        // behind the current poll's active flag.
        rescheduleRequested = true;
        return;
      }
      if (active || taskPending) return;
      runPoll(false);
    },
    pollNow(): void {
      // Re-entrancy is the one case this must refuse: a completion callback
      // asking again from inside `poll()` would recurse through the whole
      // render queue on one stack, which is what `rescheduleRequested` exists
      // to defuse.
      if (polling) return;
      if (!active) return;
      // Adopt the poll exactly as `handleTask` would, INCLUDING the
      // bookkeeping. Calling `runPoll()` while leaving `taskPending` set is not
      // a shortcut, it is a permanent wedge: a poll that completes clears
      // `active`, the already-posted task then drops on its `!active` guard
      // without ever clearing `taskPending`, and every later `schedule()`
      // returns at `if (active || taskPending)`. The scheduler stops polling
      // for good — which for the GPU fence means the frame is never observed
      // complete, `first_display_gpu_complete` is never posted, and the app
      // sits in `signaling` until the test times out.
      //
      // Bumping the generation is what makes the outstanding task harmless: it
      // arrives with a stale token and is dropped, the same way `cancel()`
      // invalidates one.
      generation = (generation + 1) >>> 0 || 1;
      taskPending = false;
      active = false;
      runPoll(false);
    },
    cancel(): void {
      active = false;
      taskPending = false;
      rescheduleRequested = false;
      inlineTaskToken = null;
      closeInlineTaskChannel();
      generation = (generation + 1) >>> 0 || 1;
    },
    handleTask(token: number): void {
      if (postingTask) {
        if (token === generation && active && taskPending) {
          inlineTaskToken = token;
        }
        return;
      }
      if (token !== generation || !active) return;
      taskPending = false;
      active = false;
      runPoll(true);
    },
  };
  return scheduler;
}

